const pages = await browser.pages.list();
const ga = pages.filter(x => (x.url || '').includes('analytics.google.com'));
if (!ga.length) { console.log('NO GA4 TAB'); return 'no'; }
const p = await browser.page(ga[ga.length - 1].pageId);
await p.goto('https://analytics.google.com/analytics/web/#/reports/explorer?params=%5B%5B%5D%5D');
await sleep(11000);
const raw = await p.evaluate(() => { try {
  const body = String((document.body && document.body.textContent) || '').replace(/\s+/g, ' ');
  const rows = Array.from(document.querySelectorAll('tr')).map(tr => Array.from(tr.querySelectorAll('td,th')).map(td => String(td.innerText||'').replace(/\s+/g,' ').trim())).filter(c => c.some(x => x));
  return { url: String(location.href).slice(0, 90), head: body.slice(0, 300), rows: rows.slice(0, 40) };
} catch (e) { return { err: String(e.message).slice(0, 80) } } });
console.log('EVENTS ' + JSON.stringify((raw && 'value' in raw) ? raw.value : raw));
return 'ok';
